#!/usr/bin/env python3
"""Draw the front page of THE WORLD TODAY for Friday 20 November 2026.

Writes one 1024x1024 PNG to $MAKEFUN_OUTPUT_DIR/entry.png (``/output``
when the variable is unset). The page sums up six stories that happened
or were first reported on Friday 20 November 2026:

  1. Cyclone Akvan makes landfall on India's Odisha coast.
  2. The EU summons Russia's ambassador after Kyiv embassy strikes.
  3. Asian markets plunge after Wall Street's 1,101-point Dow rout.
  4. New Zealand reach 317-6 at lunch on day two in Wellington.
  5. COP31 reaches its closing day in Antalya.
  6. SpaceX launches the classified USSF-317 mission.

Everything is drawn in code: a plain RGB canvas, an embedded bitmap
font (rasterized at build time from DejaVu, stored below as base64 --
no font file, no image file, no network at runtime), simple geometric
illustrations, and a hand-written PNG encoder.

Standard library only. No randomness, no timestamps, no network: two
runs produce byte-identical output.
"""

import base64
import os
import struct
import sys
import zlib

W, H = 1024, 1024
MAX_FILE_SIZE = 1024 * 1024  # 1 MiB

PAPER = (248, 244, 232)
INK = (26, 26, 26)
MUTED = (90, 86, 76)
RED = (163, 22, 33)
PANEL = (255, 255, 255)
EDGE = (200, 194, 178)
SKY = (216, 232, 240)
SLATE = (70, 90, 120)
GOLD = (212, 175, 55)
EUBLUE = (0, 51, 153)
GREEN = (46, 125, 50)
TAN = (210, 180, 140)
DARK = (16, 24, 48)

# Generated bitmap-font data (build time, DejaVu rasterizer).
# Each blob: per glyph, struct '>HHbbH' (w, h, dx, dy, advance)
# followed by w*h grayscale coverage bytes. Chars are in FONT_CHARS order.
FONT_CHARS = {}
FONT_BLOBS = {}
FONT_CHARS['r14'] = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~•°'
FONT_BLOBS['r14'] = ''
FONT_CHARS['r16'] = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~•°'
FONT_BLOBS['r16'] = ''
FONT_CHARS['b16'] = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~•°'
FONT_BLOBS['b16'] = ''
FONT_CHARS['b20'] = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~•°'
FONT_BLOBS['b20'] = ''
FONT_CHARS['b28'] = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~•°'
FONT_BLOBS['b28'] = ''
FONT_CHARS['b56'] = ' THEWORLDYAD'
FONT_BLOBS['b56'] = ''


# ---------------------------------------------------------------- canvas

class Canvas:
    """A plain RGB canvas backed by one flat bytearray."""

    def __init__(self, width, height, bg):
        self.w = width
        self.h = height
        self.buf = bytearray(bytes(bg) * (width * height))
        self.clip = None  # optional (x0, y0, x1, y1) clip rectangle

    def clip_to(self, x, y, w, h):
        self.clip = (x, y, x + w, y + h)

    def unclip(self):
        self.clip = None

    def fill_rect(self, x, y, w, h, color):
        if w <= 0 or h <= 0:
            return
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        if self.clip is not None:
            cx0, cy0, cx1, cy1 = self.clip
            x0 = max(x0, cx0)
            y0 = max(y0, cy0)
            x1 = min(x1, cx1)
            y1 = min(y1, cy1)
        if x0 >= x1 or y0 >= y1:
            return
        row = bytes(color) * (x1 - x0)
        for yy in range(y0, y1):
            start = (yy * self.w + x0) * 3
            self.buf[start:start + len(row)] = row

    def rect(self, x, y, w, h, color, thick=1):
        self.fill_rect(x, y, w, thick, color)
        self.fill_rect(x, y + h - thick, w, thick, color)
        self.fill_rect(x, y, thick, h, color)
        self.fill_rect(x + w - thick, y, thick, h, color)

    def set_pixel(self, x, y, color):
        if self.clip is not None:
            cx0, cy0, cx1, cy1 = self.clip
            if not (cx0 <= x < cx1 and cy0 <= y < cy1):
                return
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.buf[i] = color[0]
            self.buf[i + 1] = color[1]
            self.buf[i + 2] = color[2]

    def blend_pixel(self, x, y, color, cov):
        """Blend color over the canvas pixel with coverage 0..255."""
        if cov <= 0 or not (0 <= x < self.w and 0 <= y < self.h):
            return
        if self.clip is not None:
            cx0, cy0, cx1, cy1 = self.clip
            if not (cx0 <= x < cx1 and cy0 <= y < cy1):
                return
        i = (y * self.w + x) * 3
        if cov >= 255:
            self.buf[i] = color[0]
            self.buf[i + 1] = color[1]
            self.buf[i + 2] = color[2]
            return
        inv = 255 - cov
        self.buf[i] = (color[0] * cov + self.buf[i] * inv) // 255
        self.buf[i + 1] = (color[1] * cov + self.buf[i + 1] * inv) // 255
        self.buf[i + 2] = (color[2] * cov + self.buf[i + 2] * inv) // 255

    def line(self, x0, y0, x1, y1, color, thick=1):
        """Bresenham line with a square brush of the given thickness."""
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        half = thick // 2
        while True:
            self.fill_rect(x0 - half, y0 - half, thick, thick, color)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def disc(self, cx, cy, r, color):
        """Filled circle."""
        for dy in range(-r, r + 1):
            dx = int((r * r - dy * dy) ** 0.5)
            self.fill_rect(cx - dx, cy + dy, 2 * dx + 1, 1, color)

def draw_ring(canvas, cx, cy, r, color, bg, thick=2):
    """Circle outline: outer disc in color, inner disc in bg."""
    canvas.disc(cx, cy, r, color)
    canvas.disc(cx, cy, r - thick, bg)


# ---------------------------------------------------------------- fonts

_FONTS = {}


def _load_font(key):
    """Decode one embedded bitmap font into {char: glyph}."""
    chars = FONT_CHARS[key]
    raw = base64.b64decode(FONT_BLOBS[key])
    glyphs = {}
    pos = 0
    for ch in chars:
        w, h, dx, dy, adv = struct.unpack_from(">HHbbH", raw, pos)
        pos += 8
        pixels = raw[pos:pos + w * h]
        pos += w * h
        glyphs[ch] = (w, h, dx, dy, adv, pixels)
    return glyphs


def get_font(key):
    if key not in _FONTS:
        _FONTS[key] = _load_font(key)
    return _FONTS[key]


def text_width(key, text):
    font = get_font(key)
    total = 0
    for ch in text:
        glyph = font.get(ch)
        if glyph is None:
            glyph = font.get("?", (0, 0, 0, 0, 10, b""))
        total += glyph[4]
    return total


def draw_text(canvas, x, y_baseline, key, text, color):
    """Draw text with its baseline at y_baseline; returns width drawn."""
    font = get_font(key)
    cursor = x
    for ch in text:
        glyph = font.get(ch)
        if glyph is None:
            glyph = font.get("?", (0, 0, 0, 0, 10, b""))
        w, h, dx, dy, adv, pixels = glyph
        gx = cursor + dx
        gy = y_baseline + dy
        for row in range(h):
            base = row * w
            for col in range(w):
                cov = pixels[base + col]
                if cov:
                    canvas.blend_pixel(gx + col, gy + row, color, cov)
        cursor += adv
    return cursor - x


def wrap_text(key, text, max_width):
    """Greedy word wrap; returns a list of lines that fit max_width."""
    words = text.split(" ")
    lines = []
    current = ""
    for word in words:
        trial = word if not current else current + " " + word
        if text_width(key, trial) <= max_width or not current:
            current = trial
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def draw_wrapped(canvas, x, y_baseline, key, text, max_width, color, line_h):
    """Draw wrapped text; returns the baseline of the last line drawn."""
    lines = wrap_text(key, text, max_width)
    y = y_baseline
    for line in lines:
        draw_text(canvas, x, y, key, line, color)
        y += line_h
    return y - line_h


# ---------------------------------------------------------------- PNG

def png_bytes(canvas):
    """Encode the canvas as a deterministic PNG (filter 0, level 6)."""
    raw = bytearray()
    stride = canvas.w * 3
    for y in range(canvas.h):
        raw.append(0)
        raw += canvas.buf[y * stride:(y + 1) * stride]
    idat = zlib.compress(bytes(raw), 6)

    def chunk(typ, data):
        out = struct.pack(">I", len(data)) + typ + data
        out += struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", canvas.w, canvas.h, 8, 2, 0, 0, 0)
    return (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", ihdr)
        + chunk(b"IDAT", idat)
        + chunk(b"IEND", b"")
    )


# ---------------------------------------------------------------- illustrations

def draw_cyclone(canvas, x, y, w, h):
    """Spiral storm over a coastline strip."""
    canvas.fill_rect(x, y, w, h, SKY)
    cx, cy = x + w // 2 - 20, y + h // 2 - 10
    # Archimedean spiral, two arms.
    import math
    for arm in (0.0, math.pi):
        pts = []
        steps = 90
        for i in range(steps + 1):
            t = i / steps * 4.6 * math.pi + arm
            r = 6 + i / steps * 62
            px = int(cx + r * math.cos(t))
            py = int(cy + r * math.sin(t) * 0.85)
            pts.append((px, py))
        for (ax, ay), (bx, by) in zip(pts, pts[1:]):
            canvas.line(ax, ay, bx, by, SLATE, 4)
    canvas.disc(cx, cy, 12, (240, 244, 248))
    canvas.disc(cx, cy, 5, SLATE)
    # Rain streaks on the right.
    for i, (rx, ry) in enumerate([(x + w - 52, y + 22), (x + w - 34, y + 48),
                                  (x + w - 58, y + 76), (x + w - 30, y + 96)]):
        canvas.line(rx, ry, rx - 6, ry + 16, (90, 130, 170), 2)
    # Coastline strip along the bottom.
    for i in range(0, w, 8):
        canvas.fill_rect(x + i, y + h - 18 - (i % 16 == 0) * 4, 8, 18, TAN)


def draw_eu_flag(canvas, x, y, w, h):
    """EU circle of stars on blue."""
    import math
    canvas.fill_rect(x, y, w, h, EUBLUE)
    cx, cy = x + w // 2, y + h // 2
    r = 46
    for i in range(12):
        ang = -math.pi / 2 + i * math.pi / 6
        sx = int(cx + r * math.cos(ang))
        sy = int(cy + r * math.sin(ang))
        canvas.disc(sx, sy, 5, GOLD)


def draw_market_chart(canvas, x, y, w, h):
    """Red falling line chart."""
    canvas.fill_rect(x, y, w, h, PANEL)
    # Grid lines.
    for gy in (y + 30, y + 60, y + 90, y + 120):
        canvas.line(x + 6, gy, x + w - 6, gy, (228, 228, 228), 1)
    # Downward polyline with two small rebounds.
    pts = [(x + 8, y + 22), (x + 26, y + 34), (x + 44, y + 30),
           (x + 62, y + 58), (x + 80, y + 52), (x + 98, y + 88),
           (x + w - 8, y + 118)]
    for (ax, ay), (bx, by) in zip(pts, pts[1:]):
        canvas.line(ax, ay, bx, by, RED, 3)
    for (px, py) in pts:
        canvas.disc(px, py, 3, RED)
    # Down arrow at the end.
    ax, ay = x + w - 14, y + h - 18
    canvas.line(ax, ay - 14, ax, ay + 4, RED, 3)
    canvas.line(ax - 6, ay - 2, ax, ay + 6, RED, 3)
    canvas.line(ax + 6, ay - 2, ax, ay + 6, RED, 3)


def draw_cricket(canvas, x, y, w, h):
    """Green outfield, tan pitch, stumps and ball."""
    canvas.fill_rect(x, y, w, h, GREEN)
    # Pitch strip down the middle.
    px0 = x + w // 2 - 13
    canvas.fill_rect(px0, y + 6, 26, h - 12, TAN)
    canvas.line(px0, y + 36, px0 + 26, y + 36, (255, 255, 255), 2)
    canvas.line(px0, y + h - 36, px0 + 26, y + h - 36, (255, 255, 255), 2)
    # Stumps at the top crease.
    for sx in (px0 + 6, px0 + 11, px0 + 16):
        canvas.fill_rect(sx, y + 12, 3, 22, (250, 220, 90))
    # Bails.
    canvas.fill_rect(px0 + 6, y + 10, 13, 2, (250, 220, 90))
    # Red ball on the pitch near the bottom.
    canvas.disc(x + w // 2, y + h - 24, 6, (178, 34, 34))
    # Bat: simple angled blade.
    canvas.line(x + w // 2 - 22, y + h - 14, x + w // 2 - 6, y + h - 50,
               (222, 196, 150), 5)


def draw_globe(canvas, x, y, w, h):
    """Globe with a rising red temperature arrow."""
    canvas.fill_rect(x, y, w, h, SKY)
    cx, cy = x + w // 2 - 8, y + h // 2
    canvas.disc(cx, cy, 42, (30, 100, 180))
    # Continents as green blobs.
    canvas.disc(cx - 14, cy - 12, 12, (76, 175, 80))
    canvas.disc(cx + 12, cy + 8, 14, (76, 175, 80))
    canvas.disc(cx + 16, cy - 18, 8, (76, 175, 80))
    canvas.disc(cx - 18, cy + 16, 7, (76, 175, 80))
    # Rising arrow on the right.
    ax = x + w - 22
    canvas.line(ax, y + h - 30, ax, y + 26, RED, 3)
    canvas.line(ax - 7, y + 34, ax, y + 22, RED, 3)
    canvas.line(ax + 7, y + 34, ax, y + 22, RED, 3)


def draw_rocket(canvas, x, y, w, h):
    """Night sky, rocket climbing, Earth curve below."""
    canvas.fill_rect(x, y, w, h, DARK)
    # Stars.
    for (sx, sy) in [(x + 18, y + 16), (x + 52, y + 30), (x + 96, y + 12),
                     (x + 140, y + 26), (x + 200, y + 14), (x + 250, y + 34),
                     (x + 30, y + 60), (x + 230, y + 66), (x + 120, y + 48)]:
        canvas.disc(sx, sy, 2, (255, 255, 255))
    # Earth curve at the bottom (clipped to the illustration box).
    canvas.disc(x + w // 2, y + h + 150, 190, (30, 100, 180))
    canvas.disc(x + w // 2 - 40, y + h - 10, 16, (76, 175, 80))
    # Rocket body.
    rx = x + w // 2 - 90
    ry = y + 26
    canvas.fill_rect(rx, ry + 18, 22, 62, (240, 240, 240))
    # Nose cone.
    for i in range(18):
        inset = i // 2
        canvas.fill_rect(rx + inset, ry + i, 22 - 2 * inset, 1, (200, 40, 40))
    # Window.
    canvas.disc(rx + 11, ry + 38, 5, (120, 200, 235))
    # Fins.
    canvas.fill_rect(rx - 8, ry + 62, 8, 18, (200, 40, 40))
    canvas.fill_rect(rx + 22, ry + 62, 8, 18, (200, 40, 40))
    # Flame.
    for i in range(26):
        half = 8 - i // 4
        canvas.fill_rect(rx + 11 - half, ry + 80 + i, 2 * half, 1,
                         (255, 170, 40) if i < 14 else (255, 110, 30))


# ---------------------------------------------------------------- layout

def draw_panel(canvas, px, py, pw, ph, kicker, headline, body,
               illustrator):
    canvas.fill_rect(px, py, pw, ph, PANEL)
    canvas.rect(px, py, pw, ph, EDGE, 1)
    canvas.clip_to(px + 8, py + 8, 120, ph - 16)
    illustrator(canvas, px + 8, py + 8, 120, ph - 16)
    canvas.unclip()
    tx = px + 140
    tw = pw - 140 - 12
    draw_text(canvas, tx, py + 26, "b16", kicker, RED)
    hy = draw_wrapped(canvas, tx, py + 52, "b20", headline, tw, INK, 24)
    draw_wrapped(canvas, tx, hy + 26, "r14", body, tw, INK, 18)


def build_page():
    canvas = Canvas(W, H, PAPER)
    canvas.rect(8, 8, W - 16, H - 16, INK, 2)

    # Masthead.
    title = "THE WORLD TODAY"
    draw_text(canvas, (W - text_width("b56", title)) // 2, 84, "b56",
              title, INK)
    canvas.fill_rect(16, 96, W - 32, 2, INK)
    date_line = "FRIDAY 20 NOVEMBER 2026"
    draw_text(canvas, (W - text_width("b20", date_line)) // 2, 126, "b20",
              date_line, RED)
    canvas.fill_rect(16, 136, W - 32, 1, EDGE)

    # Lead story: cyclone landfall.
    lx, ly, lw, lh = 16, 142, 992, 218
    canvas.fill_rect(lx, ly, lw, lh, PANEL)
    canvas.rect(lx, ly, lw, lh, EDGE, 1)
    draw_text(canvas, lx + 16, ly + 28, "b16", "WEATHER \u2022 INDIA", RED)
    draw_text(canvas, lx + 16, ly + 66, "b28",
              "CYCLONE AKVAN HITS ODISHA COAST", INK)
    draw_wrapped(canvas, lx + 16, ly + 100, "r16",
                 "Severe storm crosses near Gopalpur at noon with winds "
                 "of 100 km/h. More than 50,000 people evacuated from "
                 "the coast; red warnings for 20-30 cm of rain and a "
                 "one-metre storm surge.",
                 592, INK, 22)
    canvas.clip_to(lx + 648, ly + 8, 336, lh - 16)
    draw_cyclone(canvas, lx + 648, ly + 8, 336, lh - 16)
    canvas.unclip()

    # Grid of four stories.
    grid = [
        (16, 376, "EUROPE", "EU SUMMONS RUSSIAN ENVOY",
         "Brussels calls in Moscow's ambassador after Russian drones "
         "damaged the Austrian and Dutch embassies and a Kyiv "
         "cathedral. One person was killed and five hurt.",
         draw_eu_flag),
        (522, 376, "MARKETS", "ASIAN MARKETS PLUNGE",
         "The Nikkei sinks 2.9% and Seoul opens 4% lower as Wall "
         "Street's 1,101-point Dow rout spreads to Asia. Chip "
         "shares lead the fall.",
         draw_market_chart),
        (16, 550, "SPORT", "PHILLIPS TON LIFTS NZ TO 317-6",
         "Glenn Phillips hits 118 and Henry Nicholls an unbeaten 146 "
         "as New Zealand reach 317 for 6 at lunch on day two of the "
         "first Test in Wellington.",
         draw_cricket),
        (522, 550, "CLIMATE", "COP31 CLOSES TODAY",
         "Talks in Antalya reach their Friday deadline with fossil "
         "fuels stripped from the draft deal. The text is the first "
         "to admit the 1.5\u00b0C goal will be overshot.",
         draw_globe),
    ]
    for (px, py, kicker, headline, body, illustrator) in grid:
        draw_panel(canvas, px, py, 486, 158, kicker, headline, body,
                   illustrator)

    # Bottom story: SpaceX launch.
    bx, by, bw, bh = 16, 724, 992, 160
    canvas.fill_rect(bx, by, bw, bh, PANEL)
    canvas.rect(bx, by, bw, bh, EDGE, 1)
    draw_text(canvas, bx + 16, by + 28, "b16", "SPACE", RED)
    draw_text(canvas, bx + 16, by + 64, "b28",
              "SPACEX LAUNCHES SECRET USSF-317", INK)
    draw_wrapped(canvas, bx + 16, by + 96, "r16",
                 "A Falcon 9 lifts a classified Space Force payload "
                 "from Vandenberg at 04:32 UTC; booster B1100 flies "
                 "for the 11th time. China launches a SatNet batch "
                 "from Wenchang at noon.",
                 652, INK, 22)
    canvas.clip_to(bx + 700, by + 8, 284, bh - 16)
    draw_rocket(canvas, bx + 700, by + 8, 284, bh - 16)
    canvas.unclip()

    # Also-today strip.
    canvas.fill_rect(16, 896, W - 32, 1, EDGE)
    draw_text(canvas, 32, 930, "b16", "ALSO TODAY", RED)
    draw_wrapped(canvas, 170, 918, "r14",
                 "Trump holds a White House news conference at noon "
                 "\u2022 Anthropic's $81.3bn share offering closes "
                 "\u2022 SpaceX Dragon CRS-35 undocks from the ISS "
                 "at 17:05 UTC",
                 822, INK, 18)
    canvas.fill_rect(16, 952, W - 32, 1, EDGE)

    # Footer.
    footer = "SIX STORIES FROM ONE DAY \u2022 THE WORLD TODAY"
    draw_text(canvas, (W - text_width("r14", footer)) // 2, 988, "r14",
              footer, MUTED)
    return canvas


# ---------------------------------------------------------------- main

def fail(message):
    print("error: %s" % message, file=sys.stderr)
    sys.exit(1)


def validate_png(data):
    """Check the encoded PNG end to end: signature, chunk CRCs, IHDR
    dimensions, a single IEND at the very end. Exits non-zero on failure."""
    if len(data) == 0:
        fail("encoded PNG is empty")
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        fail("encoded PNG does not start with the PNG signature")
    offset = 8
    seen_ihdr = False
    seen_iend = False
    while offset < len(data):
        if offset + 8 > len(data):
            fail("truncated chunk header at byte %d" % offset)
        length = struct.unpack(">I", data[offset:offset + 4])[0]
        chunk_type = data[offset + 4:offset + 8]
        chunk_end = offset + 8 + length
        if chunk_end + 4 > len(data):
            fail("chunk %r at byte %d overruns the end of the file"
                 % (chunk_type.decode("ascii", "replace"), offset))
        chunk_data = data[offset + 8:chunk_end]
        stored_crc = struct.unpack(">I", data[chunk_end:chunk_end + 4])[0]
        actual_crc = zlib.crc32(chunk_type + chunk_data) & 0xFFFFFFFF
        if actual_crc != stored_crc:
            fail("chunk %r at byte %d has a bad CRC (stored %08x, "
                 "computed %08x)"
                 % (chunk_type.decode("ascii", "replace"), offset,
                    stored_crc, actual_crc))
        if not seen_ihdr:
            if chunk_type != b"IHDR" or length != 13:
                fail("first chunk is not a 13-byte IHDR")
            width, height = struct.unpack(">II", chunk_data[:8])
            if width != W or height != H:
                fail("image is %dx%d, expected %dx%d"
                     % (width, height, W, H))
            seen_ihdr = True
        if chunk_type == b"IEND":
            if length != 0 or chunk_end + 4 != len(data):
                fail("IEND chunk is not the last chunk")
            seen_iend = True
            break
        offset = chunk_end + 4
    if not seen_ihdr:
        fail("encoded PNG has no IHDR chunk")
    if not seen_iend:
        fail("encoded PNG has no IEND chunk")


def main():
    canvas = build_page()
    data = png_bytes(canvas)
    validate_png(data)
    if len(data) > MAX_FILE_SIZE:
        fail("entry.png is %d bytes, larger than the 1 MiB limit"
             % len(data))
    output_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
    output_path = os.path.join(output_dir, "entry.png")
    try:
        os.makedirs(output_dir, exist_ok=True)
        with open(output_path, "wb") as handle:
            handle.write(data)
    except OSError as exc:
        fail("cannot write %s: %s" % (output_path, exc))
    if os.path.getsize(output_path) != len(data):
        fail("wrote %s but its size does not match (%d bytes)"
             % (output_path, len(data)))
    print("wrote %s (1024x1024, %d bytes)" % (output_path, len(data)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
